function latest(obs, sec, type, session) {
	return obs.filter((o) => o.permanent_security_id === sec && o.snapshot_type === type && (!session || o.session_date === session)).sort((a, b) => a.received_at < b.received_at ? 1 : -1)[0] ?? null;
}
function buildMemberSnapshot(sec, sessionDate, nextSession, ev, obs) {
	const pins = [];
	const add = (row) => {
		if (!row) return;
		pins.push({
			id: row.observation_id,
			hash: asHex(row.observation_hash)
		});
	};
	add(obs.find((o) => o.observation_id === ev.source_observation_id) ?? latest(obs, sec, "EARNINGS_EVENT", sessionDate) ?? null);
	const quote = latest(obs, sec, "QUOTE", sessionDate);
	add(quote);
	const tape = latest(obs, sec, "TAPE_RELATIVE", sessionDate);
	add(tape);
	let rel5 = null;
	let rel63 = null;
	if (tape) {
		const p = payloadOf(tape);
		rel5 = typeof p.rel5 === "string" ? p.rel5 : null;
		rel63 = typeof p.rel63 === "string" ? p.rel63 : null;
	} else {
		const stockBars = obs.filter((o) => o.permanent_security_id === sec && o.snapshot_type === "BAR_DAILY" && o.session_date < sessionDate).sort((a, b) => a.session_date < b.session_date ? -1 : 1);
		const spyBars = obs.filter((o) => o.permanent_security_id === "SEC-SPY" && o.snapshot_type === "BAR_DAILY" && o.session_date < sessionDate).sort((a, b) => a.session_date < b.session_date ? -1 : 1);
		const take = (n) => {
			const s = stockBars.slice(-n);
			const b = spyBars.slice(-n);
			s.forEach(add);
			b.forEach(add);
			return {
				sf: s.map((r) => String(payloadOf(r).factor ?? "1.000000000000")),
				bf: b.map((r) => String(payloadOf(r).factor ?? "1.000000000000"))
			};
		};
		const h5 = take(5);
		const h63 = take(63);
		rel5 = h5.sf.length === 5 ? benchmarkRelative(h5.sf, h5.bf) : null;
		rel63 = h63.sf.length === 63 ? benchmarkRelative(h63.sf, h63.bf) : null;
	}
	const chain = obs.filter((o) => o.permanent_security_id === sec && o.snapshot_type === "OPTION_LEG" && o.session_date === sessionDate);
	chain.forEach(add);
	const stockMid = quote ? String(payloadOf(quote).mid ?? payloadOf(quote).last ?? "") : "";
	let optionsValid = false;
	let move = null;
	if (stockMid && chain.length) {
		const legs = chain.map((o) => {
			const p = payloadOf(o);
			return {
				right: p.right,
				strike: String(p.strike),
				expiry: String(p.expiry),
				bid: String(p.bid),
				ask: String(p.ask),
				oi: Number(p.oi),
				volume: Number(p.volume),
				asOf: o.source_event_at ?? o.received_at
			};
		});
		const sel = selectStraddle(stockMid, sessionDate, etInstant(nextSession, "09:30").toISOString(), legs);
		if ("call" in sel && sel.valid) {
			move = impliedMove(((Number(sel.call.bid) + Number(sel.call.ask)) / 2).toFixed(6), ((Number(sel.put.bid) + Number(sel.put.ask)) / 2).toFixed(6), Number(stockMid).toFixed(6));
			optionsValid = move != null;
		}
	}
	const card = assembleCard({
		timingQuality: ev.quality,
		optionsValid,
		impliedMove: move,
		rel5,
		rel63
	});
	const pinList = [...new Map(pins.map((p) => [p.id, p])).values()].sort((a, b) => a.id < b.id ? -1 : 1);
	return {
		card,
		snapHash: snapshotHash({
			permanent_security_id: sec,
			event_key: ev.event_key,
			session_date: sessionDate,
			card,
			pins: pinList
		}),
		pins: pinList
	};
}
async function nextOpen(sql, from, n) {
	const rows = await sql.query(`SELECT session_date::text FROM calendar_session
     WHERE calendar_version = 'cal-2026' AND listing_exchange = 'XNYS' AND is_open = TRUE AND session_date > $1
     ORDER BY session_date ASC LIMIT $2`, [from, n]);
	if (rows.length < n) throw new DeskError("CALENDAR_BLOCKED", "cannot resolve D+n");
	return rows[n - 1].session_date;
}
