async function applyEntryCorrection(commandId, positionId, newPrice, actor) {
	const prior = await loadExistingCommand(await getSql(), commandId);
	if (prior) return prior;
	return withWriter(actor, async (ctx) => {
		const pos = await ctx.sql.query(`SELECT position_id, state, original_reserved_notional::text, last_book_vintage_id FROM "position" WHERE position_id = $1 FOR UPDATE`, [positionId]);
		if (!pos.length) throw new DeskError("NOT_FOUND", "position missing", 404);
		const fill = modeledFill(newPrice);
		const exit = (await ctx.sql.query(`SELECT values FROM book_vintage WHERE book_vintage_id = $1`, [pos[0].last_book_vintage_id]))[0]?.values?.exit_price;
		const pnl = exit ? paperPnl(pos[0].original_reserved_notional, exit, fill, "0.0000") : null;
		await appendEvent(ctx, {
			commandId,
			type: "REVISE",
			payload: {
				position_id: positionId,
				new_price: newPrice
			},
			receipt: {
				fill,
				pnl
			}
		});
		await writeBook(ctx, positionId, "ORIGINAL_PLAN", {
			modeled_fill: fill,
			exit_price: exit,
			paper_pnl: pnl,
			original_notional: pos[0].original_reserved_notional,
			revision_reason: "ENTRY_PRICE_CORRECTION"
		}, true);
		return {
			position_id: positionId,
			state: pos[0].state,
			modeled_fill: fill,
			paper_pnl: pnl,
			original_notional: pos[0].original_reserved_notional
		};
	});
}
