function openDates() {
	const out = [];
	const d = new Date(Date.UTC(2026, 5, 1));
	const end = new Date(Date.UTC(2026, 8, 18));
	while (d <= end) {
		const iso = d.toISOString().slice(0, 10);
		const dow = d.getUTCDay();
		if (!(dow === 0 || dow === 6 || iso === "2026-09-07")) out.push(iso);
		d.setUTCDate(d.getUTCDate() + 1);
	}
	return out;
}
async function insertObs(sql, seq, row) {
	const payloadH = payloadHash(row.payload);
	const envelope = {
		observation_id: row.id,
		permanent_security_id: row.sec,
		event_key: row.eventKey ?? null,
		session_date: row.session,
		snapshot_type: row.type,
		provider_id: "fixture",
		provider_record_id: row.id,
		provider_revision: "1",
		payload_hash: payloadH,
		payload_schema_version: "1",
		source_class: row.sourceClass ?? "AUTHORITATIVE",
		adjustment_basis: row.type.startsWith("MARK") || row.type === "QUOTE" || row.type === "BAR_DAILY" ? "UNADJUSTED" : "NOT_PRICE",
		payload: row.payload
	};
	const obsH = observationHash(envelope);
	await sql.query(`INSERT INTO observation (
      observation_id, event_seq, permanent_security_id, event_key, session_date, snapshot_type, provider_id,
      provider_record_id, provider_revision, received_at, source_event_at, source_class, adjustment_basis,
      payload_schema_id, payload_hash, observation_hash, envelope, is_partial, partition, tombstoned
    ) VALUES ($1,$2,$3,$4,$5,$6,'fixture',$1,'1',$7,$7,$8,$9,'1',$10,$11,$12::jsonb,FALSE,'RESEARCH',FALSE)`, [
		row.id,
		seq,
		row.sec,
		row.eventKey ?? null,
		row.session,
		row.type,
		row.receivedAt,
		envelope.source_class,
		envelope.adjustment_basis,
		hexBuf(payloadH),
		hexBuf(obsH),
		JSON.stringify(envelope)
	]);
}
var bootChain = null;
async function ensureBootstrapped() {
	if (bootChain) return bootChain;
	bootChain = (async () => {
		if ((await (await getSql()).query(`SELECT completed FROM bootstrap_state WHERE singleton_key = TRUE`))[0]?.completed) return {
			ok: true,
			note: "already-seeded"
		};
		await seedWorld();
		return {
			ok: true,
			note: "seeded"
		};
	})().then((r) => {
		console.info("[trading-app] bootstrap", r.note);
		return r;
	}).catch((err) => {
		bootChain = null;
		console.error("[trading-app] bootstrap failed", err);
		throw err;
	});
	return bootChain;
}
async function clockIso() {
	return (await (await getSql()).query(`SELECT now_utc::text FROM fixture_clock WHERE singleton_key = TRUE`))[0].now_utc;
}
async function ensureClock(iso) {
	const cur = new Date(await clockIso());
	if (new Date(iso) > cur) await advanceClock(iso, SERVICE);
}
async function runSession(opts) {
	const sql = await getSql();
	let man = await sql.query(`SELECT manifest_id FROM manifest WHERE session_date = $1`, [opts.sessionDate]);
	if (!man.length) {
		await ensureClock(etInstant(opts.sessionDate, "15:45").toISOString());
		if (opts.beforeSeal) await opts.beforeSeal();
		await sealSession(opts.commandSeal, opts.sessionDate, SERVICE);
		man = await sql.query(`SELECT manifest_id FROM manifest WHERE session_date = $1`, [opts.sessionDate]);
	}
	const members = await sql.query(`SELECT permanent_security_id, shuffle_order_index FROM manifest_member WHERE manifest_id = $1 ORDER BY shuffle_order_index`, [man[0].manifest_id]);
	await ensureClock(etInstant(opts.sessionDate, "15:46").toISOString());
	const ordered = opts.echoLast ? [...members.filter((m) => m.permanent_security_id !== "SEC-ECHO"), ...members.filter((m) => m.permanent_security_id === "SEC-ECHO")] : members;
	for (const m of ordered) {
		if (opts.skip.has(m.permanent_security_id)) continue;
		if ((await sql.query(`SELECT 1 FROM "freeze" WHERE manifest_id = $1 AND permanent_security_id = $2`, [man[0].manifest_id, m.permanent_security_id])).length) continue;
		await refreshQuote(m.permanent_security_id, opts.sessionDate);
		try {
			await freezeMember(`cmd-frz-${opts.freezePrefix}-${m.permanent_security_id}`, man[0].manifest_id, m.permanent_security_id, SERVICE);
		} catch (err) {
			if (err instanceof DeskError && err.code === "OFF_DESIGN_EARLY_RELEASE") continue;
			throw err;
		}
	}
	await ensureClock(etInstant(opts.sessionDate, "15:47").toISOString());
	await applyDueDeadlines(SERVICE);
}
